def min_paint_for_beauty(n, m, k, colors, paint_costs):
    from functools import lru_cache
    import sys

    sys.setrecursionlimit(10**6)

    # Helper function to calculate beauty
    def calculate_beauty(color_sequence):
        if not color_sequence:
            return 0
        beauty = 1
        current_color = color_sequence[0]
        for color in color_sequence[1:]:
            if color != current_color:
                beauty += 1
                current_color = color
        return beauty

    # Recursive function with memoization to find minimum paint
    @lru_cache(None)
    def dp(i, last_color, current_beauty):
        if i == n:
            return 0 if current_beauty == k else float('inf')

        if colors[i] != 0:
            # If the tree is already colored, just check the next
            return dp(i + 1, colors[i], current_beauty + (1 if colors[i] != last_color else 0))

        min_cost = float('inf')
        for color in range(1, m + 1):
            next_beauty = current_beauty + (1 if color != last_color else 0)
            if next_beauty > k:
                break
            cost = paint_costs[i][color - 1] + dp(i + 1, color, next_beauty)
            min_cost = min(min_cost, cost)

        return min_cost

    # Call the dp function starting with no color and beauty 0
    result = dp(0, 0, 0)
    return result if result != float('inf') else -1

