    from functools import lru_cache

    @lru_cache(None)
    def dp(index, last_color, groups):
        if index == n:
            return 0 if groups == k else float('inf')

        if groups > k:
            return float('inf')

        min_cost = float('inf')

        if colors[index] != 0:
            # Tree is already colored
            min_cost = dp(index + 1, colors[index], groups + (1 if colors[index] != last_color else 0))
        else:
            # Try coloring this tree with each color
            for color in range(1, m + 1):
                cost = paint_costs[index][color - 1]
                next_groups = groups + (1 if color != last_color else 0)
                min_cost = min(min_cost, cost + dp(index + 1, color, next_groups))

        return min_cost

    result = dp(0, 0, 0)
    return result if result != float('inf') else -1

